uint16_t ns_f32_to_f16(float f) {
    uint32_t u;
    memcpy(&u, &f, 4);
    const uint32_t s = (u >> 16) & 0x8000u, a = u & 0x7FFFFFFFu;
    if (a > 0x7F800000u) return (uint16_t) (s | 0x7E00u);    // NaN
    if (a >= 0x477FF000u) return (uint16_t) (s | 0x7C00u);   // 65520 and above round to infinity
    if (a >= 0x38800000u) {                                  // normal: 10 of 23 mantissa bits, rounded
        const uint32_t r = a - 0x38000000u;
        return (uint16_t) (s | ((r + 0xFFFu + ((r >> 13) & 1u)) >> 13));
    }
    const int sh = 126 - (int) (a >> 23);   // subnormal: the value in steps of 2^-24
    if (sh > 24) return (uint16_t) s;
    const uint32_t m = (a & 0x7FFFFFu) | 0x800000u, q = m >> sh, rem = m & ((1u << sh) - 1), half = 1u << (sh - 1);
    return (uint16_t) (s | (q + (rem > half || (rem == half && (q & 1)))));
}

void ns_q8_0_row(const float* x, int n, uint8_t* out) {
    for (int b = 0; b < n / 32; ++b, x += 32, out += 34) {
        float amax = 0.0f;
        for (int j = 0; j < 32; ++j) amax = fabsf(x[j]) > amax ? fabsf(x[j]) : amax;
        const float d = amax / 127, id = d != 0.0f ? 1.0f / d : 0.0f;
        const uint16_t h = ns_f32_to_f16(d);
        out[0] = (uint8_t) h;
        out[1] = (uint8_t) (h >> 8);
        for (int j = 0; j < 32; ++j) out[2 + j] = (uint8_t) (int8_t) roundf(x[j] * id);
    }
}

static float f16_to_f32(uint16_t h) {
    const int e = h >> 10 & 31, m = h & 0x3FF;
    const float v = e ? ldexpf(1.0f + (float) m / 1024.0f, e - 15) : ldexpf((float) m / 1024.0f, -14);
    return h & 0x8000 ? -v : v;
}

// The engine's name of the shard's dense tensor g, else 0
static int dense_name(const char* g, char* out, size_t len) {
    static const char* kTop[][2] = {
        {"output.weight", "language_model.lm_head.weight"}, {"token_embd.weight", "language_model.model.embed_tokens.weight"},
        {"output_hc_up.weight", "language_model.model.hyper_connection_mixer.input_mix_weight_up.weight"},
        {"output_hc_down.weight", "language_model.model.hyper_connection_mixer.input_mix_weight_down.weight"}};
    static const char* kBlk[][2] = {
        {"attn_qkv", "linear_attn.in_proj_qkv"}, {"attn_gate", "linear_attn.in_proj_z"}, {"ssm_out", "linear_attn.out_proj"},
        {"ssm_alpha", "linear_attn.in_proj_a"}, {"ssm_beta", "linear_attn.in_proj_b"}, {"attn_q", "self_attn.q_proj"},
        {"attn_k", "self_attn.k_proj"}, {"attn_v", "self_attn.v_proj"}, {"attn_output", "self_attn.o_proj"},
        {"ffn_gate_shexp", "mlp.shared_expert.gate_proj"}, {"ffn_up_shexp", "mlp.shared_expert.up_proj"},
        {"ffn_down_shexp", "mlp.shared_expert.down_proj"}, {"hc_attn_up", "attn_hyper_connection.input_mix_weight_up"},
        {"hc_attn_down", "attn_hyper_connection.input_mix_weight_down"}, {"hc_attn_inject", "attn_hyper_connection.block_inject_weight"},
        {"hc_ffn_up", "mlp_hyper_connection.input_mix_weight_up"}, {"hc_ffn_down", "mlp_hyper_connection.input_mix_weight_down"},
        {"hc_ffn_inject", "mlp_hyper_connection.block_inject_weight"}};
    for (size_t i = 0; i < sizeof kTop / sizeof kTop[0]; ++i)
        if (!strcmp(g, kTop[i][0])) return snprintf(out, len, "%s", kTop[i][1]) > 0;
    char k[32];
    int l = -1, at = 0;
    if (sscanf(g, "blk.%d.%31[a-z_].weight%n", &l, k, &at) != 2 || g[at]) return 0;
    for (size_t i = 0; i < sizeof kBlk / sizeof kBlk[0]; ++i)
        if (!strcmp(k, kBlk[i][0])) return snprintf(out, len, "language_model.model.layers.%d.%s.weight", l, kBlk[i][1]) > 0;
    return 0;
}

// A DeltaNet tensor's value-head axis: none, rows by head (a, b), rows by head block (z), the v rows of qkv, columns (out)
enum { GDN_NONE, GDN_HEADS, GDN_BLOCKS, GDN_QKV, GDN_COLS };
static int gdn_kind(const char* name) {
    static const char* kSuf[] = {"in_proj_a.weight", "in_proj_b.weight", "in_proj_z.weight", "in_proj_qkv.weight", "out_proj.weight"};
    static const int kKind[] = {GDN_HEADS, GDN_HEADS, GDN_BLOCKS, GDN_QKV, GDN_COLS};
    const char* at = strstr(name, ".linear_attn.");
    for (int i = 0; at && i < 5; ++i) if (!strcmp(at + 13, kSuf[i])) return kKind[i];
    return GDN_NONE;
}
static int vhead(const NsGdnHeads* q, int h) { return h % q->hk * (q->hv / q->hk) + h / q->hk; }   // llama.cpp's h: MLX's
static int gdn_ok(const NsGdnHeads* q, int kind, const NsTensor* t) {
    const int vd = q->hv * q->dv;
    return kind == GDN_HEADS ? t->rows == q->hv : kind == GDN_BLOCKS ? t->rows == vd : kind == GDN_QKV ? t->rows == 2 * q->hk * q->dk + vd :
           kind == GDN_COLS ? t->cols == vd : 1;
}
// Row r of the shard's tensor from the pack's t, in llama.cpp's head order (tmp: t->cols floats for the columns)
static void shard_row(const NsRows* nr, const NsTensor* t, const NsGdnHeads* q, int kind, int r, float* w, float* tmp) {
    const int v0 = kind == GDN_QKV ? 2 * q->hk * q->dk : 0, dv = q ? q->dv : 1;
    if (kind == GDN_COLS) {
        ns_row_f32(nr, t, 0, r, 0, tmp);
        for (int c = 0; c < t->cols; ++c) w[c] = tmp[vhead(q, c / dv) * dv + c % dv];
        return;
    }
    const int src = kind == GDN_HEADS ? vhead(q, r) : (kind == GDN_BLOCKS || kind == GDN_QKV) && r >= v0 ?
                    v0 + vhead(q, (r - v0) / dv) * dv + (r - v0) % dv : r;
    ns_row_f32(nr, t, 0, src, 0, w);
}

typedef struct { const NsTensor* t[NS_EMU_PACKS]; uint64_t off; int lp; } EmTensor;   // lp: 3 L + p, or a DeltaNet kind   // + Q8_0 offset, 3 L + p
typedef struct {
    const EmTensor* t;
    const uint8_t* map;
    const NsRows* nr;
    size_t len, cols;           // the largest tensor slice in bytes, the most columns
    int fd, items, next, bad;   // item k: expert k % slices of tensor k / slices (all tensors of a shard share slices)
    pthread_mutex_t mu;
} Emu;

static void* emu_worker(void* arg) {
    Emu* m = (Emu*) arg;
    uint8_t* buf = (uint8_t*) malloc(m->len);
    float* w = (float*) malloc(4 * m->cols);
    for (;;) {
        pthread_mutex_lock(&m->mu);
        const int k = m->bad ? m->items : m->next++;
        pthread_mutex_unlock(&m->mu);
        if (k >= m->items) break;
        const EmTensor* et = &m->t[k / m->t[0].t[0]->slices];
        const int e = k % et->t[0]->slices;
        const NsTensor* t = et->t[m->map ? m->map[(size_t) et->lp * (size_t) et->t[0]->slices + (size_t) e] : 0];
        const size_t rb = (size_t) t->cols / 32 * 34, len = rb * (size_t) t->rows;
        for (int r = 0; r < t->rows; ++r) {
            ns_row_f32(m->nr, t, e, r, 0, w);
            ns_q8_0_row(w, t->cols, buf + rb * (size_t) r);
        }
        size_t done = 0;
        const uint64_t at = et->off + (uint64_t) e * len;
        while (done < len) {
            const ssize_t n = pwrite(m->fd, buf + done, len - done, (off_t) (at + done));
            if (n <= 0) break;
            done += (size_t) n;
        }
        if (done < len) { pthread_mutex_lock(&m->mu); m->bad = 1; pthread_mutex_unlock(&m->mu); }
    }
    free(buf);
    free(w);
    return NULL;
}

int ns_emulate_gguf(const NsModel* const* packs, int np, const uint8_t* map, size_t map_len, const char* gguf, int workers,
                    int* n, char* err, int errlen) {
    static const char* kProj[3] = {"gate", "up", "down"};
    *n = 0;
    if (np < 1 || np > NS_EMU_PACKS) { snprintf(err, (size_t) errlen, "%d packs: 1 to %d", np, NS_EMU_PACKS); return -1; }
    Gguf g;
    if (gguf_open(&g, gguf, err, errlen)) return -1;
    EmTensor* et = (EmTensor*) malloc(sizeof *et * (size_t) (g.n ? g.n : 1));
    int nt = 0, rc = 0;
    size_t len = 0, cols = 0;
    for (int i = 0; i < g.n && !rc; ++i) {   // check every expert tensor first
        const GgufTensor* gt = &g.t[i];
        char proj[8], name[128];
        int l = 0, at = 0, p = 0;
        if (sscanf(gt->name, "blk.%d.ffn_%7[a-z]_exps.weight%n", &l, proj, &at) != 2 || gt->name[at]) continue;
        while (p < 3 && strcmp(kProj[p], proj)) ++p;
        if (p == 3) continue;
        snprintf(name, sizeof name, "language_model.model.layers.%d.mlp.switch_mlp.%s_proj.weight", l, proj);
        EmTensor x = {{NULL}, g.data + gt->offset, 3 * l + p};
        for (int k = 0; k < np && !rc; ++k) {
            const NsTensor* t = x.t[k] = ns_find(packs[k], name);
            if (!t) rc = snprintf(err, (size_t) errlen, "%s: pack %d has no %s", gguf, k, name);
            else if (gt->type != 8 || gt->ndim != 3 || gt->dims[0] != t->cols || gt->dims[1] != t->rows || gt->dims[2] != t->slices ||
                     t->cols % 32 || t->enc == NS_SEED6P8 || (nt && t->slices != et[0].t[0]->slices) ||
                     g.data + gt->offset + (uint64_t) t->slices * (uint64_t) t->rows * (uint64_t) (t->cols / 32) * 34 > g.size)
                rc = snprintf(err, (size_t) errlen, "%s: %s is not Q8_0 [%d][%d][%d] like %s of pack %d", gguf, gt->name, t->slices,
                              t->rows, t->cols, name, k);
        }
        if (rc) break;
        const NsTensor* t0 = x.t[0];
        const size_t E = (size_t) t0->slices, lp = (size_t) x.lp, rb = (size_t) t0->rows * (size_t) (t0->cols / 32) * 34;
        if (map && (lp + 1) * E > map_len) rc = snprintf(err, (size_t) errlen, "the map has no %s", gt->name);
        for (size_t e = 0; map && !rc && e < E; ++e)
            if (map[lp * E + e] >= np) rc = snprintf(err, (size_t) errlen, "the map takes %s from pack %d", gt->name, map[lp * E + e]);
        if (rc) break;
        et[nt++] = x;
        if (rb > len) len = rb;
        if ((size_t) t0->cols > cols) cols = (size_t) t0->cols;
    }
    gguf_close(&g);   // before the writes: the mapping is read-only
    if (rc || !nt) { free(et); return rc ? -1 : 0; }
    NsRows* nr = (NsRows*) malloc(sizeof *nr);
    ns_rows_init(nr);
    Emu m = {et, map, nr, len, cols, open(gguf, O_RDWR), nt * et[0].t[0]->slices, 0, 0, PTHREAD_MUTEX_INITIALIZER};
    if (m.fd < 0) rc = snprintf(err, (size_t) errlen, "%s: cannot open for writing", gguf);
    else {
        pthread_t th[64];
        const int nw = workers < 1 ? 1 : workers > 64 ? 64 : workers;
        for (int i = 0; i < nw; ++i) pthread_create(&th[i], NULL, emu_worker, &m);
        for (int i = 0; i < nw; ++i) pthread_join(th[i], NULL);
        if (close(m.fd) || m.bad) rc = snprintf(err, (size_t) errlen, "%s: a write failed", gguf);
    }
    free(nr);
    free(et);
    *n = rc ? 0 : nt;
    return rc ? -1 : 0;
}

int ns_emulate_dense(const NsModel* pack, const NsGdnHeads* gdn, const char* only, const char* gguf, int* n, char* err, int errlen) {
    *n = 0;
    Gguf g;
    if (gguf_open(&g, gguf, err, errlen)) return -1;
    EmTensor* et = (EmTensor*) malloc(sizeof *et * (size_t) (g.n ? g.n : 1));
    NsRows* nr = (NsRows*) malloc(sizeof *nr);
    ns_rows_init(nr);
    float* w = NULL, *tmp = NULL;
    uint8_t* buf = NULL;
    int nt = 0, rc = 0;
    if (gdn && (gdn->hk < 1 || gdn->hv % gdn->hk || gdn->dv < 1)) rc = snprintf(err, (size_t) errlen, "DeltaNet heads %d / %d", gdn->hk, gdn->hv);
    for (int i = 0; i < g.n && !rc; ++i) {   // check every dense tensor first
        const GgufTensor* gt = &g.t[i];
        char name[160];
        if (!dense_name(gt->name, name, sizeof name) || (only && !strstr(name, only))) continue;
        const NsTensor* t = ns_find(pack, name);
        const size_t rb = t ? (size_t) t->cols / 32 * 34 : 0;
        const int kind = gdn ? gdn_kind(name) : GDN_NONE;
        if (!t || gt->type != 8 || gt->ndim != 2 || gt->dims[0] != t->cols || gt->dims[1] != t->rows || !(gdn ? gdn_ok(gdn, kind, t) : 1) ||
            t->slices != 1 || t->cols % 32 || g.data + gt->offset + rb * (uint64_t) t->rows > g.size) {
            rc = snprintf(err, (size_t) errlen, "%s: %s is not Q8_0 like the pack's %s", gguf, gt->name, name);
            break;
        }
        w = (float*) realloc(w, sizeof(float) * (size_t) t->cols);
        tmp = (float*) realloc(tmp, sizeof(float) * (size_t) t->cols);
        double e2 = 0, w2 = 0;
        const int ns = t->rows < 16 ? t->rows : 16;
        for (int k = 0; k < ns; ++k) {   // the row order: 16 rows spread over the tensor, against the shard's own
            const int r = (int) ((int64_t) k * t->rows / ns);
            const uint8_t* q = (const uint8_t*) gguf_data(&g, gt) + rb * (size_t) r;
            shard_row(nr, t, gdn, kind, r, w, tmp);
            for (int c = 0; c < t->cols; ++c) {
                const uint8_t* b = q + (size_t) c / 32 * 34;
                const double v = (double) f16_to_f32((uint16_t) (b[0] | b[1] << 8)) * (int8_t) b[2 + c % 32];
                e2 += (w[c] - v) * (w[c] - v);
                w2 += v * v;
            }
        }
        if (e2 > 0.09 * w2) {
            rc = snprintf(err, (size_t) errlen, "%s: %s is %.2f from the pack's %s: another row order", gguf, gt->name, sqrt(e2 / (w2 > 0 ? w2 : 1)), name);
            break;
        }
        et[nt++] = (EmTensor) {{t}, g.data + gt->offset, kind};
    }
    gguf_close(&g);   // before the writes: the mapping is read-only
    const int fd = rc || !nt ? -1 : open(gguf, O_RDWR);
    if (!rc && nt && fd < 0) rc = snprintf(err, (size_t) errlen, "%s: cannot open for writing", gguf);
    for (int i = 0; fd >= 0 && !rc && i < nt; ++i) {
        const NsTensor* t = et[i].t[0];
        const size_t rb = (size_t) t->cols / 32 * 34;
        w = (float*) realloc(w, sizeof(float) * (size_t) t->cols);
        tmp = (float*) realloc(tmp, sizeof(float) * (size_t) t->cols);
        buf = (uint8_t*) realloc(buf, rb);
        for (int r = 0; !rc && r < t->rows; ++r) {
            shard_row(nr, t, gdn, et[i].lp, r, w, tmp);
            ns_q8_0_row(w, t->cols, buf);
            if (pwrite(fd, buf, rb, (off_t) (et[i].off + rb * (uint64_t) r)) != (ssize_t) rb) rc = snprintf(err, (size_t) errlen, "%s: a write failed", gguf);
        }
    }
    if (fd >= 0 && close(fd) && !rc) rc = snprintf(err, (size_t) errlen, "%s: a write failed", gguf);
    free(w); free(tmp); free(buf); free(nr); free(et);
    *n = rc ? 0 : nt;
    return rc ? -1 : 0;
}
// nslm/lib_format.c - see format.h.  C99 + POSIX mmap.
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#include "format.h"

static const char* skip_ws(const char* p, const char* e) { while (p < e && (*p == ' ' || *p == '\n' || *p == '\r' || *p == '\t')) ++p; return p; }

static const char* parse_str(const char* p, const char* e, char* out, int cap) {
    if (p >= e || *p != '"') return NULL;
    ++p;
    int n = 0;
    while (p < e && *p != '"') {
        if (*p == '\\' && p + 1 < e) ++p;
        if (n < cap - 1) out[n++] = *p;
        ++p;
    }
    out[n] = 0;
    return p < e ? p + 1 : NULL;
}

static const char* skip_value(const char* p, const char* e) {   // any JSON value (for __metadata__)
    p = skip_ws(p, e);
    if (p >= e) return NULL;
    if (*p == '"') { char tmp[8]; return parse_str(p, e, tmp, sizeof tmp); }
    if (*p == '{' || *p == '[') {
        int depth = 0, in_str = 0;
        for (; p < e; ++p) {
            if (in_str) { if (*p == '\\') ++p; else if (*p == '"') in_str = 0; continue; }
            if (*p == '"') in_str = 1;
            else if (*p == '{' || *p == '[') ++depth;
            else if (*p == '}' || *p == ']') { if (--depth == 0) return p + 1; }
        }
        return NULL;
    }
    while (p < e && *p != ',' && *p != '}') ++p;
    return p;
}

int st_open_file(StFile* s, const char* path, char* err, int errlen) {
    memset(s, 0, sizeof *s);
    const int fd = open(path, O_RDONLY);
    if (fd < 0) { snprintf(err, (size_t) errlen, "%s: %s", path, strerror(errno)); return -1; }
    struct stat sb;
    fstat(fd, &sb);
    s->size = (size_t) sb.st_size;
    void* m = mmap(NULL, s->size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    if (m == MAP_FAILED) { snprintf(err, (size_t) errlen, "%s: mmap failed", path); return -1; }
    s->map = (const uint8_t*) m;
    uint64_t hn;
    memcpy(&hn, s->map, 8);
    s->data = 8 + hn;
    const char* p = (const char*) s->map + 8, *e = p + hn;
    int cap = 512;
    s->e = (StEntry*) calloc((size_t) cap, sizeof(StEntry));
    p = skip_ws(p, e);
    if (p >= e || *p != '{') goto bad;
    ++p;
    for (;;) {
        p = skip_ws(p, e);
        if (p < e && *p == '}') break;
        char key[96];
        if (!(p = parse_str(p, e, key, sizeof key))) goto bad;
        p = skip_ws(p, e);
        if (p >= e || *p != ':') goto bad;
        p = skip_ws(p + 1, e);
        if (!strcmp(key, "__metadata__")) {
            if (!(p = skip_value(p, e))) goto bad;
        } else {
            if (s->n == cap) {
                cap *= 2;
                s->e = (StEntry*) realloc(s->e, sizeof(StEntry) * (size_t) cap);
            }
            StEntry* t = &s->e[s->n++];
            snprintf(t->name, sizeof t->name, "%s", key);
            if (*p != '{') goto bad;
            ++p;
            for (;;) {
                p = skip_ws(p, e);
                if (*p == '}') { ++p; break; }
                char f[32];
                if (!(p = parse_str(p, e, f, sizeof f))) goto bad;
                p = skip_ws(p, e);
                if (*p != ':') goto bad;
                p = skip_ws(p + 1, e);
                if (!strcmp(f, "dtype")) {
                    if (!(p = parse_str(p, e, t->dtype, sizeof t->dtype))) goto bad;
                } else if (!strcmp(f, "shape") || !strcmp(f, "data_offsets")) {
                    if (*p != '[') goto bad;
                    ++p;
                    int64_t v[8];
                    int k = 0;
                    for (;;) {
                        p = skip_ws(p, e);
                        if (*p == ']') { ++p; break; }
                        char* q;
                        const long long x = strtoll(p, &q, 10);
                        if (q == p || k >= 8) goto bad;
                        v[k++] = x;
                        p = skip_ws(q, e);
                        if (*p == ',') ++p;
                    }
                    if (f[0] == 's') { t->ndim = k; memcpy(t->shape, v, sizeof(int64_t) * (size_t) k); }
                    else { if (k != 2) goto bad; t->begin = (uint64_t) v[0]; t->end = (uint64_t) v[1]; }
                } else {
                    if (!(p = skip_value(p, e))) goto bad;
                }
                p = skip_ws(p, e);
                if (*p == ',') ++p;
            }
        }
        p = skip_ws(p, e);
        if (*p == ',') ++p;
    }
    return 0;
bad:
    snprintf(err, (size_t) errlen, "%s: cannot parse the safetensors header", path);
    st_close_file(s);
    return -1;
}

void st_willneed(const void* p, uint64_t n) {
    const uintptr_t a = (uintptr_t) p & ~(uintptr_t) 16383;   // a multiple of 4 KiB and 16 KiB pages
    if (n) madvise((void*) a, (size_t) ((uintptr_t) p + n - a), MADV_WILLNEED);
}

void st_dontneed(const void* p, uint64_t n) {
    const uintptr_t a = ((uintptr_t) p + 16383) & ~(uintptr_t) 16383, b = ((uintptr_t) p + n) & ~(uintptr_t) 16383;
    if (b > a) madvise((void*) a, (size_t) (b - a), MADV_DONTNEED);   // only pages inside the range: a neighbour's stay
}

void st_close_file(StFile* s) {
    if (s->map) munmap((void*) s->map, s->size);
    free(s->e);
    memset(s, 0, sizeof *s);
}

const StEntry* st_find(const StFile* s, const char* name) {
    for (int i = 0; i < s->n; ++i) if (!strcmp(s->e[i].name, name)) return &s->e[i];
    return NULL;
}
// nslm/lib_gguf.c - see gguf.h.  C99 + POSIX mmap.
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

#include "gguf.h"

typedef struct { const uint8_t* p; size_t n, i; int bad; } Rd;

static uint64_t rd(Rd* r, int w) {   // little-endian unsigned of w bytes
    uint64_t v = 0;
    if (r->bad || r->i + (size_t) w > r->n) { r->bad = 1; return 0; }
    for (int k = 0; k < w; ++k) v |= (uint64_t) r->p[r->i + (size_t) k] << (8 * k);
    r->i += (size_t) w;
    return v;
}
static void skip(Rd* r, uint64_t n) { if (r->bad || n > r->n - r->i) r->bad = 1; else r->i += (size_t) n; }

static const int kWidth[13] = {1, 1, 2, 2, 4, 4, 4, 1, 0, 0, 8, 8, 8};   // GGUF value types; 8 string, 9 array
static void skip_value(Rd* r, uint32_t type, int depth) {
    if (type == 8) { skip(r, rd(r, 8)); return; }
    if (type == 9 && depth < 4) {
        const uint32_t et = (uint32_t) rd(r, 4);
        const uint64_t n = rd(r, 8);
        if (n > r->n) { r->bad = 1; return; }
        if (et != 8 && et != 9 && et < 13) { skip(r, n * (uint64_t) kWidth[et]); return; }
        for (uint64_t k = 0; k < n && !r->bad; ++k) skip_value(r, et, depth + 1);
        return;
    }
    if (type < 13 && kWidth[type]) { skip(r, (uint64_t) kWidth[type]); return; }
    r->bad = 1;
}

int gguf_open(Gguf* g, const char* path, char* err, int errlen) {
    memset(g, 0, sizeof *g);
    const int fd = open(path, O_RDONLY);
    if (fd < 0) { snprintf(err, (size_t) errlen, "%s: %s", path, strerror(errno)); return -1; }
    struct stat sb;
    fstat(fd, &sb);
    g->size = (size_t) sb.st_size;
    void* m = g->size ? mmap(NULL, g->size, PROT_READ, MAP_PRIVATE, fd, 0) : MAP_FAILED;
    close(fd);
    if (m == MAP_FAILED) { snprintf(err, (size_t) errlen, "%s: mmap failed", path); return -1; }
    g->map = (const uint8_t*) m;
    Rd r = {g->map, g->size, 0, 0};
    const uint64_t magic = rd(&r, 4), ver = rd(&r, 4), nt = rd(&r, 8), nkv = rd(&r, 8);
    uint64_t align = 32;
    if (r.bad || magic != 0x46554747u || (ver != 2 && ver != 3) || nt > (1u << 24)) goto bad;
    for (uint64_t k = 0; k < nkv && !r.bad; ++k) {
        const uint64_t kl = rd(&r, 8);
        const size_t k0 = r.i;
        skip(&r, kl);
        const uint32_t type = (uint32_t) rd(&r, 4);
        if (!r.bad && kl == 17 && !memcmp(r.p + k0, "general.alignment", 17) && type == 4) align = rd(&r, 4);
        else skip_value(&r, type, 0);
    }
    if (r.bad || !align || align > 4096) goto bad;
    g->t = (GgufTensor*) calloc(nt ? (size_t) nt : 1, sizeof(GgufTensor));
    for (uint64_t k = 0; k < nt && !r.bad; ++k) {
        GgufTensor* t = &g->t[g->n];
        const uint64_t nl = rd(&r, 8);
        if (nl >= sizeof t->name || nl > r.n - r.i) { r.bad = 1; break; }
        memcpy(t->name, r.p + r.i, (size_t) nl);
        r.i += (size_t) nl;
        t->ndim = (int) rd(&r, 4);
        if (t->ndim < 1 || t->ndim > 4) { r.bad = 1; break; }
        for (int d = 0; d < t->ndim; ++d) t->dims[d] = (int64_t) rd(&r, 8);
        t->type = (uint32_t) rd(&r, 4);
        t->offset = rd(&r, 8);
        ++g->n;
    }
    g->data = (r.i + align - 1) / align * align;
    for (int k = 0; k < g->n && !r.bad; ++k) if (g->data + g->t[k].offset > g->size) r.bad = 1;
    if (r.bad) goto bad;
    return 0;
bad:
    snprintf(err, (size_t) errlen, "%s: not a readable GGUF file", path);
    gguf_close(g);
    return -1;
}

void gguf_close(Gguf* g) {
    if (g->map) munmap((void*) g->map, g->size);
    free(g->t);
    memset(g, 0, sizeof *g);
}

const GgufTensor* gguf_find(const Gguf* g, const char* name) {
    for (int k = 0; k < g->n; ++k) if (!strcmp(g->t[k].name, name)) return &g->t[k];
    return NULL;
}

const float* gguf_f32(const Gguf* g, const char* name, int64_t n) {
    const GgufTensor* t = gguf_find(g, name);
    if (!t || t->type != GGUF_F32) return NULL;
    int64_t m = 1;
    for (int d = 0; d < t->ndim; ++d) m *= t->dims[d];
    if (m != n || g->data + t->offset + 4 * (uint64_t) n > g->size) return NULL;
    return (const float*) gguf_data(g, t);
}
// nslm/lib_gptq.c - nslm_gptq (gptq.h): GPTQ-style error feedback over a seed search of any block codec.
#include "gptq.h"

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "linalg.h"
#include "search4.h"

// W[r][c1:] -= sum_q E[r][q] U[c0 + q][c1:] for rows r0 .. r1 of every slice
typedef struct { int ns, R, C, c0, ne, c1, r0, r1; float* const* W; const float* E; const double* const* U; } FbJob;
static void* fb_rows(void* arg) {
    const FbJob* j = (const FbJob*) arg;
    for (int s = 0; s < j->ns; ++s)
        for (int r = j->r0; r < j->r1; ++r) {
            float* wr = j->W[s] + (size_t) r * j->C;
            const float* er = j->E + ((size_t) s * j->R + r) * 128;
            for (int q = 0; q < j->ne; ++q) {
                const float eq = er[q];
                const double* ur = j->U[s] + (size_t) (j->c0 + q) * j->C;
                for (int c = j->c1; c < j->C; ++c) wr[c] -= eq * (float) ur[c];
            }
        }
    return NULL;
}
static void feedback(int threads, int ns, int R, int C, int c0, int ne, int c1, float* const* W, const float* E, const double* const* U) {
    enum { NT = 32 };
    const int nt = threads < 1 ? 1 : threads > NT ? NT : threads, per = (R + nt - 1) / nt;
    FbJob jb[NT];
    pthread_t th[NT];
    for (int i = 0; i < nt; ++i) jb[i] = (FbJob) {ns, R, C, c0, ne, c1, i * per < R ? i * per : R, (i + 1) * per < R ? (i + 1) * per : R, W, E, U};
    if (nt == 1) { fb_rows(&jb[0]); return; }
    for (int i = 0; i < nt; ++i) pthread_create(&th[i], NULL, fb_rows, &jb[i]);
    for (int i = 0; i < nt; ++i) pthread_join(th[i], NULL);
}

int nslm_gptq(const NslmGptq* q, int ns, int R, int C, float* const* W, const double* const* U, const int* bias,
              uint16_t* const* seed, uint32_t* const* coef, uint8_t* const* ecode, char* err, int errlen) {
    if (ns < 1 || R < 1 || C < 8 || C % 8) { snprintf(err, (size_t) errlen, "gptq: bad shape"); return -1; }
    const int ng = C / 8;
    int* ord = malloc(sizeof(int) * (size_t) ns);   // the slices by bias (stable): runs of one bias search together
    for (int i = 0; i < ns; ++i) ord[i] = i;
    for (int i = 1; i < ns; ++i)
        for (int k = i; k > 0 && bias[ord[k - 1]] > bias[ord[k]]; --k) { const int t = ord[k]; ord[k] = ord[k - 1]; ord[k - 1] = t; }
    float* wb = malloc(sizeof(float) * (size_t) R * 8 * ns), *A = malloc(sizeof(float) * 64 * (size_t) ns);
    float* E = malloc(sizeof(float) * (size_t) ns * R * 128);   // per slice, this batch's errors E = (W_b - Q_b) T [R][128]
    double* T = malloc(sizeof(double) * 64 * (size_t) ns);
    uint16_t* sb = malloc(2 * (size_t) R * ns);
    uint32_t* cb = malloc(4 * (size_t) R * ns);
    uint8_t* eb = malloc((size_t) R * ns);
    int rc = 0;
    for (int bb = 0; bb < ng && !rc; bb += 16) {   // batches of 16 column groups (lazy feedback)
        const int b1 = bb + 16 < ng ? bb + 16 : ng, c0 = bb * 8, c1 = b1 * 8;
        for (int b = bb; b < b1 && !rc; ++b) {
            const int g0 = b * 8;
            for (int k0 = 0; k0 < ns && !rc;) {
                int k1 = k0 + 1;
                while (k1 < ns && bias[ord[k1]] == bias[ord[k0]]) ++k1;
                const int n = k1 - k0;
                for (int i = 0; i < n; ++i) {
                    const int s = ord[k0 + i];
                    double* t = T + (size_t) s * 64;
                    nslm_upper8_inverse(U[s] + (size_t) g0 * C + g0, C, t);
                    for (int r = 0; r < 8; ++r)
                        for (int c = 0; c < 8; ++c) A[(size_t) i * 64 + r * 8 + c] = (float) t[c * 8 + r];   // A = T^T
                    for (int r = 0; r < R; ++r) memcpy(wb + ((size_t) r * n + i) * 8, W[s] + (size_t) r * C + g0, sizeof(float) * 8);
                }
                if ((rc = q->search(q->ctx, wb, R, 8 * n, A, bias[ord[k0]], sb, cb, eb, err, errlen))) break;
                for (int i = 0; i < n; ++i) {
                    const int s = ord[k0 + i];
                    const double* t = T + (size_t) s * 64;
                    for (int r = 0; r < R; ++r) {
                        const size_t k = (size_t) r * n + i, o = (size_t) r * ng + b;
                        seed[s][o] = sb[k]; coef[s][o] = cb[k]; ecode[s][o] = eb[k];
                        uint16_t bf[8];
                        q->decode(sb[k], cb[k], bias[s] + eb[k], bf);
                        double d[8];
                        for (int c = 0; c < 8; ++c) d[c] = (double) wb[k * 8 + c] - nslm4_bf2f(bf[c]);
                        float* er = E + ((size_t) s * R + r) * 128 + (g0 - c0);
                        for (int j = 0; j < 8; ++j) {
                            double a = 0;
                            for (int c = 0; c <= j; ++c) a += d[c] * t[c * 8 + j];
                            er[j] = (float) a;
                        }
                        float* wr = W[s] + (size_t) r * C;   // this batch's later groups take this group's error now
                        for (int j = 0; j < 8; ++j) {
                            const float eq = er[j];
                            const double* ur = U[s] + (size_t) (g0 + j) * C;
                            for (int c = g0 + 8; c < c1; ++c) wr[c] -= eq * (float) ur[c];
                        }
                    }
                }
                k0 = k1;
            }
        }
        if (!rc && c1 < C) feedback(q->threads, ns, R, C, c0, c1 - c0, c1, W, E, U);   // the later batches
    }
    free(ord); free(wb); free(A); free(E); free(T); free(sb); free(cb); free(eb);
    return rc ? -1 : 0;
}
// nslm/lib_gptq4.c - nslm4_gptq (gptq4.h): nslm_gptq (gptq.h) over the P = 4 search's 16-bit coefficient words.
#include "gptq4.h"

#include <stdlib.h>

#include "gptq.h"
#include "search4.h"

typedef struct { Nslm4SearchA search; void* ctx; } Ctx4;
static int search32(void* ctx, const float* w, int rows, int cols, const float* A, int bias, uint16_t* seed, uint32_t* coef,
                    uint8_t* ecode, char* err, int errlen) {
    const Ctx4* c = (const Ctx4*) ctx;
    const size_t nb = (size_t) rows * cols / 8;
    uint16_t* c16 = malloc(2 * nb);
    const int rc = c->search(c->ctx, w, rows, cols, A, bias, seed, c16, ecode, err, errlen);
    for (size_t k = 0; k < nb; ++k) coef[k] = c16[k];
    free(c16);
    return rc;
}
static void decode4(uint16_t seed, uint32_t coef, int e, uint16_t bf[8]) { nslm4_decode_block(seed, (uint16_t) coef, e, bf); }

int nslm4_gptq(Nslm4SearchA search, void* ctx, int ns, int R, int C, float* const* W, const double* const* U, const int* bias,
               uint16_t* const* seed, uint16_t* const* coef, uint8_t* const* ecode, char* err, int errlen) {
    Ctx4 c = {search, ctx};
    const NslmGptq q = {search32, decode4, &c, 1};
    const size_t nb = (size_t) R * (C / 8);
    uint32_t** c32 = calloc((size_t) (ns > 0 ? ns : 1), sizeof(uint32_t*));
    for (int s = 0; s < ns; ++s) c32[s] = malloc(4 * nb);
    const int rc = nslm_gptq(&q, ns, R, C, W, U, bias, seed, c32, ecode, err, errlen);
    for (int s = 0; s < ns; ++s) {
        if (!rc)
            for (size_t k = 0; k < nb; ++k) coef[s][k] = (uint16_t) c32[s][k];
        free(c32[s]);
    }
    free(c32);
    return rc;
}
// nslm/lib_json.c - see json.h.
#include "json.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void buf_put(Buf* b, const char* s, size_t n) {
    if (b->n + n + 1 > b->cap) {
        b->cap = (b->n + n + 1) * 2;
        b->p = (char*) realloc(b->p, b->cap);
    }
    memcpy(b->p + b->n, s, n);
    b->n += n;
    b->p[b->n] = 0;
}
void buf_puts(Buf* b, const char* s) { buf_put(b, s, strlen(s)); }
char* buf_take(Buf* b) {
    if (!b->p) buf_put(b, "", 0);
    char* p = b->p;
    b->p = NULL;
    b->n = b->cap = 0;
    return p;
}

Json* json_new(JType t) {
    Json* j = (Json*) calloc(1, sizeof(Json));
    j->t = t;
    return j;
}
Json* json_str(const char* s) {
    Json* j = json_new(J_STR);
    j->s = strdup(s);
    return j;
}
void json_push(Json* a, Json* v) {
    a->v = (Json**) realloc(a->v, sizeof(Json*) * (size_t) (a->n + 1));
    a->v[a->n++] = v;
}
void json_set(Json* o, const char* key, Json* v) {
    for (int i = 0; i < o->n; ++i)
        if (!strcmp(o->k[i], key)) { json_free(o->v[i]); o->v[i] = v; return; }
    o->k = (char**) realloc(o->k, sizeof(char*) * (size_t) (o->n + 1));
    o->k[o->n] = strdup(key);
    json_push(o, v);
}
void json_free(Json* j) {
    if (!j) return;
    for (int i = 0; i < j->n; ++i) {
        json_free(j->v[i]);
        if (j->k) free(j->k[i]);
    }
    free(j->v);
    free(j->k);
    free(j->s);
    free(j);
}
Json* json_copy(const Json* j) {
    Json* c = json_new(j->t);
    c->i = j->i;
    c->d = j->d;
    if (j->s) c->s = strdup(j->s);
    for (int i = 0; i < j->n; ++i) {
        if (j->t == J_OBJ) json_set(c, j->k[i], json_copy(j->v[i]));
        else json_push(c, json_copy(j->v[i]));
    }
    return c;
}
Json* json_get(const Json* o, const char* key) {
    if (!o || o->t != J_OBJ) return NULL;
    for (int i = 0; i < o->n; ++i)
        if (!strcmp(o->k[i], key)) return o->v[i];
    return NULL;
}
const char* json_gets(const Json* o, const char* key) {
    const Json* v = json_get(o, key);
    return v && v->t == J_STR ? v->s : NULL;
}
int json_truthy(const Json* j) {
    if (!j) return 0;
    switch (j->t) {
    case J_NULL: case J_FALSE: return 0;
    case J_TRUE: return 1;
    case J_INT: return j->i != 0;
    case J_NUM: return j->d != 0;
    case J_STR: return j->s[0] != 0;
    default: return j->n > 0;
    }
}

// ---- parser ----

typedef struct {
    const char* s;
    size_t n, i;
    char* err;
    int errlen;
    int depth;
} P;

static Json* fail(P* p, const char* msg) {
    if (p->err && !p->err[0]) snprintf(p->err, (size_t) p->errlen, "JSON: %s at byte %zu", msg, p->i);
    return NULL;
}
static void ws(P* p) {
    while (p->i < p->n && (p->s[p->i] == ' ' || p->s[p->i] == '\t' || p->s[p->i] == '\n' || p->s[p->i] == '\r')) ++p->i;
}
static int hex4(P* p, unsigned* u) {
    if (p->i + 4 > p->n) return 0;
    *u = 0;
    for (int k = 0; k < 4; ++k) {
        const char c = p->s[p->i++];
        *u = *u * 16 + (unsigned) (c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10
                                   : c >= 'A' && c <= 'F' ? c - 'A' + 10 : 99);
        if (*u > 0xFFFF) return 0;
    }
    return 1;
}
static void utf8(Buf* b, unsigned c) {
    char o[4];
    if (c < 0x80) { o[0] = (char) c; buf_put(b, o, 1); }
    else if (c < 0x800) { o[0] = (char) (0xC0 | c >> 6); o[1] = (char) (0x80 | (c & 63)); buf_put(b, o, 2); }
    else if (c < 0x10000) {
        o[0] = (char) (0xE0 | c >> 12); o[1] = (char) (0x80 | ((c >> 6) & 63)); o[2] = (char) (0x80 | (c & 63));
        buf_put(b, o, 3);
    } else {
        o[0] = (char) (0xF0 | c >> 18); o[1] = (char) (0x80 | ((c >> 12) & 63));
        o[2] = (char) (0x80 | ((c >> 6) & 63)); o[3] = (char) (0x80 | (c & 63));
        buf_put(b, o, 4);
    }
}
static char* pstring(P* p) {
    Buf b = {0};
    ++p->i;   // opening quote
    for (;;) {
        if (p->i >= p->n) { free(b.p); fail(p, "unterminated string"); return NULL; }
        const char c = p->s[p->i++];
        if (c == '"') break;
        if ((unsigned char) c < 0x20) { free(b.p); fail(p, "control character in string"); return NULL; }
        if (c != '\\') { buf_put(&b, &c, 1); continue; }
        if (p->i >= p->n) break;
        const char e = p->s[p->i++];
        unsigned u, lo;
        switch (e) {
        case '"': buf_put(&b, "\"", 1); break;
        case '\\': buf_put(&b, "\\", 1); break;
        case '/': buf_put(&b, "/", 1); break;
        case 'b': buf_put(&b, "\b", 1); break;
        case 'f': buf_put(&b, "\f", 1); break;
        case 'n': buf_put(&b, "\n", 1); break;
        case 'r': buf_put(&b, "\r", 1); break;
        case 't': buf_put(&b, "\t", 1); break;
        case 'u':
            if (!hex4(p, &u)) { free(b.p); fail(p, "bad \\u escape"); return NULL; }
            if (u >= 0xD800 && u < 0xDC00 && p->i + 6 <= p->n && p->s[p->i] == '\\' && p->s[p->i + 1] == 'u') {
                const size_t save = p->i;
                p->i += 2;
                if (hex4(p, &lo) && lo >= 0xDC00 && lo < 0xE000) u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00);
                else p->i = save;
            }
            utf8(&b, u);
            break;
        default: free(b.p); fail(p, "bad escape"); return NULL;
        }
    }
    return buf_take(&b);
}
static Json* pvalue(P* p);
static Json* pvalue(P* p) {
    ws(p);
    if (p->i >= p->n) return fail(p, "unexpected end");
    if (++p->depth > 512) return fail(p, "nesting too deep");
    const char c = p->s[p->i];
    Json* j = NULL;
    if (c == '{') {
        j = json_new(J_OBJ);
        ++p->i;
        ws(p);
        if (p->i < p->n && p->s[p->i] == '}') ++p->i;
        else for (;;) {
            ws(p);
            if (p->i >= p->n || p->s[p->i] != '"') { json_free(j); return fail(p, "expected key"); }
            char* key = pstring(p);
            if (!key) { json_free(j); return NULL; }
            ws(p);
            if (p->i >= p->n || p->s[p->i] != ':') { free(key); json_free(j); return fail(p, "expected ':'"); }
            ++p->i;
            Json* v = pvalue(p);
            if (!v) { free(key); json_free(j); return NULL; }
            json_set(j, key, v);   // a repeated key keeps its first position and the last value, as Python
            free(key);
            ws(p);
            if (p->i < p->n && p->s[p->i] == ',') { ++p->i; continue; }
            if (p->i < p->n && p->s[p->i] == '}') { ++p->i; break; }
            json_free(j);
            return fail(p, "expected ',' or '}'");
        }
    } else if (c == '[') {
        j = json_new(J_ARR);
        ++p->i;
        ws(p);
        if (p->i < p->n && p->s[p->i] == ']') ++p->i;
        else for (;;) {
            Json* v = pvalue(p);
            if (!v) { json_free(j); return NULL; }
            json_push(j, v);
            ws(p);
            if (p->i < p->n && p->s[p->i] == ',') { ++p->i; continue; }
            if (p->i < p->n && p->s[p->i] == ']') { ++p->i; break; }
            json_free(j);
            return fail(p, "expected ',' or ']'");
        }
    } else if (c == '"') {
        char* s = pstring(p);
        if (!s) return NULL;
        j = json_new(J_STR);
        j->s = s;
    } else if (!strncmp(p->s + p->i, "true", 4)) { p->i += 4; j = json_new(J_TRUE); }
    else if (!strncmp(p->s + p->i, "false", 5)) { p->i += 5; j = json_new(J_FALSE); }
    else if (!strncmp(p->s + p->i, "null", 4)) { p->i += 4; j = json_new(J_NULL); }
    else if (c == '-' || (c >= '0' && c <= '9')) {
        const size_t st = p->i;
        int flt = 0;
        if (p->s[p->i] == '-') ++p->i;
        while (p->i < p->n && strchr("0123456789.eE+-", p->s[p->i])) {
            if (strchr(".eE", p->s[p->i])) flt = 1;
            ++p->i;
        }
        char tmp[64];
        const size_t len = p->i - st;
        if (len >= sizeof tmp) return fail(p, "number too long");
        memcpy(tmp, p->s + st, len);
        tmp[len] = 0;
        char* end;
        if (!flt) {
            const long long v = strtoll(tmp, &end, 10);
            if (*end) return fail(p, "bad number");
            j = json_new(J_INT);
            j->i = v;
        } else {
            const double v = strtod(tmp, &end);
            if (*end) return fail(p, "bad number");
            j = json_new(J_NUM);
            j->d = v;
        }
    } else return fail(p, "unexpected character");
    --p->depth;
    return j;
}
Json* json_parse(const char* s, size_t n, char* err, int errlen) {
    P p = {s, n, 0, err, errlen, 0};
    if (err && errlen) err[0] = 0;
    Json* j = pvalue(&p);
    if (!j) return NULL;
    ws(&p);
    if (p.i != p.n) { json_free(j); return fail(&p, "trailing data"); }
    return j;
}

Json* json_parse_prefix(const char* s, size_t n, size_t* used) {
    P p = {s, n, 0, NULL, 0, 0};
    Json* j = pvalue(&p);
    if (j && used) *used = p.i;
    return j;
}

// ---- output ----

void py_num(Buf* b, const Json* j) {
    char t[64];
    if (j->t == J_INT) { snprintf(t, sizeof t, "%lld", (long long) j->i); buf_puts(b, t); return; }
    const double d = j->d;
    if (isnan(d)) { buf_puts(b, "NaN"); return; }
    if (isinf(d)) { buf_puts(b, d < 0 ? "-Infinity" : "Infinity"); return; }
    // the shortest digits that round-trip, then Python's repr layout
    int prec = 1;
    for (; prec < 17; ++prec) {
        snprintf(t, sizeof t, "%.*e", prec - 1, d);
        if (strtod(t, NULL) == d) break;
    }
    snprintf(t, sizeof t, "%.*e", prec - 1, d);
    char digits[32];
    int nd = 0, neg = t[0] == '-';
    const char* q = t + neg;
    for (; *q && *q != 'e'; ++q) if (*q != '.') digits[nd++] = *q;
    while (nd > 1 && digits[nd - 1] == '0') --nd;
    digits[nd] = 0;
    const int exp10 = atoi(q + 1);
    if (neg) buf_puts(b, "-");
    if (exp10 < -4 || exp10 >= 16) {
        buf_put(b, digits, 1);
        if (nd > 1) { buf_puts(b, "."); buf_put(b, digits + 1, (size_t) nd - 1); }
        snprintf(t, sizeof t, "e%c%02d", exp10 < 0 ? '-' : '+', exp10 < 0 ? -exp10 : exp10);
        buf_puts(b, t);
    } else if (exp10 < 0) {
        buf_puts(b, "0.");
        for (int k = 0; k < -exp10 - 1; ++k) buf_puts(b, "0");
        buf_put(b, digits, (size_t) nd);
    } else {
        for (int k = 0; k <= exp10; ++k) buf_put(b, k < nd ? digits + k : "0", 1);
        buf_puts(b, ".");
        if (nd > exp10 + 1) buf_put(b, digits + exp10 + 1, (size_t) (nd - exp10 - 1));
        else buf_puts(b, "0");
    }
}
// Length of the valid UTF-8 sequence at s (1 .. 4), or 0 (overlong forms, surrogates and code points past U+10FFFF are
// invalid, as RFC 3629).
static int utf8_seq(const unsigned char* s) {
    const unsigned c = s[0];
    if (c < 0x80) return 1;
    int n;
    unsigned cp;
    if (c >= 0xC2 && c <= 0xDF) { n = 2; cp = c & 0x1F; }
    else if (c >= 0xE0 && c <= 0xEF) { n = 3; cp = c & 0x0F; }
    else if (c >= 0xF0 && c <= 0xF4) { n = 4; cp = c & 0x07; }
    else return 0;
    for (int i = 1; i < n; ++i) {
        if ((s[i] & 0xC0) != 0x80) return 0;   // also stops at the terminating 0
        cp = cp << 6 | (s[i] & 0x3Fu);
    }
    if ((n == 3 && (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF))) || (n == 4 && (cp < 0x10000 || cp > 0x10FFFF))) return 0;
    return n;
}
// A JSON string; bytes that are not valid UTF-8 (a model can sample any byte token) become U+FFFD, one per byte, so the
// output is always valid JSON text (RFC 8259).
static void dump_str(Buf* b, const char* s) {
    buf_puts(b, "\"");
    for (; *s; ++s) {
        const unsigned char c = (unsigned char) *s;
        char e[8];
        if (c >= 0x80) {
            const int n = utf8_seq((const unsigned char*) s);
            if (n) { buf_put(b, s, (size_t) n); s += n - 1; }
            else buf_puts(b, "\xEF\xBF\xBD");
            continue;
        }
        if (c == '"') buf_puts(b, "\\\"");
        else if (c == '\\') buf_puts(b, "\\\\");
        else if (c == '\n') buf_puts(b, "\\n");
        else if (c == '\r') buf_puts(b, "\\r");
        else if (c == '\t') buf_puts(b, "\\t");
        else if (c == '\b') buf_puts(b, "\\b");
        else if (c == '\f') buf_puts(b, "\\f");
        else if (c < 0x20) { snprintf(e, sizeof e, "\\u%04x", c); buf_puts(b, e); }
        else buf_put(b, (const char*) &c, 1);
    }
    buf_puts(b, "\"");
}
void json_dump(Buf* b, const Json* j, int compact) {
    switch (j->t) {
    case J_NULL: buf_puts(b, "null"); break;
    case J_FALSE: buf_puts(b, "false"); break;
    case J_TRUE: buf_puts(b, "true"); break;
    case J_INT: case J_NUM: py_num(b, j); break;
    case J_STR: dump_str(b, j->s); break;
    case J_ARR:
        buf_puts(b, "[");
        for (int i = 0; i < j->n; ++i) {
            if (i) buf_puts(b, compact ? "," : ", ");
            json_dump(b, j->v[i], compact);
        }
        buf_puts(b, "]");
        break;
    case J_OBJ:
        buf_puts(b, "{");
        for (int i = 0; i < j->n; ++i) {
            if (i) buf_puts(b, compact ? "," : ", ");
            dump_str(b, j->k[i]);
            buf_puts(b, compact ? ":" : ": ");
            json_dump(b, j->v[i], compact);
        }
        buf_puts(b, "}");
        break;
    }
}
char* json_dumps(const Json* j, int compact) {
    Buf b = {0};
    json_dump(&b, j, compact);
    return buf_take(&b);
}

static void nl(Buf* b, int depth) {
    buf_puts(b, "\n");
    for (int i = 0; i < depth; ++i) buf_puts(b, "  ");
}
void json_dump_indent(Buf* b, const Json* j, int depth) {
    if ((j->t != J_ARR && j->t != J_OBJ) || !j->n) { json_dump(b, j, 0); return; }
    buf_puts(b, j->t == J_ARR ? "[" : "{");
    for (int i = 0; i < j->n; ++i) {
        if (i) buf_puts(b, ",");
        nl(b, depth + 1);
        if (j->t == J_OBJ) { dump_str(b, j->k[i]); buf_puts(b, ": "); }
        json_dump_indent(b, j->v[i], depth + 1);
    }
    nl(b, depth);
    buf_puts(b, j->t == J_ARR ? "]" : "}");
}
// nslm/lib_linalg.c - the dense linear algebra of GPTQ-style error feedback (S-01 S3), in double, C99.  Dot products sum
// four interleaved lanes (x + y + z + w at the end), portably (MSVC, GCC, Clang): the same results everywhere.
//
// GPTQ needs U, the upper Cholesky factor of the inverse Hessian: H^-1 = U^T U.  With J the order reversal and
// J H J = M M^T (lower Cholesky), H = (J M J)(J M J)^T, so H^-1 = (J M^-1 J)^T (J M^-1 J): U = J M^-1 J, upper
// triangular with a positive diagonal.  One Cholesky and one triangular inverse, 2n^3/3 flops.
#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "linalg.h"

// sum_k<n a[k] b[k] in four lanes (k mod 4) for the whole fours, the lanes added in order, then the rest one by one
static inline double dot4(const double* a, const double* b, int n) {
    double l0 = 0, l1 = 0, l2 = 0, l3 = 0;
    int k = 0;
    for (; k + 4 <= n; k += 4) { l0 += a[k] * b[k]; l1 += a[k + 1] * b[k + 1]; l2 += a[k + 2] * b[k + 2]; l3 += a[k + 3] * b[k + 3]; }
    double s = l0 + l1 + l2 + l3;
    for (; k < n; ++k) s += a[k] * b[k];
    return s;
}

// In-place lower Cholesky of a (n x n, row-major, symmetric): a = L L^T, L in the lower triangle, upper set to 0.
// Returns 0, or -1 (and the failing column + 1 in *bad) when a pivot is not positive.
static int chol_lower(double* a, int n, int* bad) {
    for (int j = 0; j < n; ++j) {
        double* rj = a + (size_t) j * n;
        double d = rj[j];
        d -= dot4(rj, rj, j);   // sum_k<j L[j][k]^2
        if (!(d > 0)) { if (bad) *bad = j + 1; return -1; }
        const double ljj = sqrt(d), inv = 1.0 / ljj;
        rj[j] = ljj;
        for (int i = j + 1; i < n; ++i) {
            double* ri = a + (size_t) i * n;
            ri[j] = (ri[j] - dot4(ri, rj, j)) * inv;
        }
    }
    for (int i = 0; i < n; ++i) memset(a + (size_t) i * n + i + 1, 0, sizeof(double) * (size_t) (n - i - 1));
    return 0;
}

// In-place inverse of a lower-triangular l (n x n): column by column, forward substitution on the identity.
static void tri_lower_inverse(double* l, int n) {
    double* inv = (double*) calloc((size_t) n * n, sizeof(double));
    double* col = (double*) malloc(sizeof(double) * (size_t) n);
    for (int j = 0; j < n; ++j) {
        // solve L x = e_j: x[i] = 0 for i < j
        memset(col, 0, sizeof(double) * (size_t) n);
        col[j] = 1.0 / l[(size_t) j * n + j];
        for (int i = j + 1; i < n; ++i) {
            const double* ri = l + (size_t) i * n;
            col[i] = -dot4(ri + j, col + j, i - j) / ri[i];
        }
        for (int i = j; i < n; ++i) inv[(size_t) i * n + j] = col[i];
    }
    memcpy(l, inv, sizeof(double) * (size_t) n * n);
    free(inv);
    free(col);
}

int nslm_gptq_factor(const double* h, int n, double damp, double* u, double* damp_used) {
    // dampen: H + damp * mean(diag H) * I (GPTQ's default damp = 0.01); dead inputs (zero diagonal) get the same floor
    double md = 0;
    for (int i = 0; i < n; ++i) md += h[(size_t) i * n + i];
    md /= n;
    const double add = damp * (md > 0 ? md : 1.0);
    if (damp_used) *damp_used = add;
    // u <- J (H + add I) J
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) u[(size_t) i * n + j] = h[(size_t) (n - 1 - i) * n + (n - 1 - j)] + (i == j ? add : 0.0);
    int bad = 0;
    if (chol_lower(u, n, &bad)) return -bad;
    tri_lower_inverse(u, n);   // M^-1 (lower)
    // U = J M^-1 J: reverse rows and columns (lower becomes upper)
    for (int i = 0; i < n / 2; ++i)
        for (int j = 0; j < n; ++j) {
            const double t = u[(size_t) i * n + j];
            u[(size_t) i * n + j] = u[(size_t) (n - 1 - i) * n + (n - 1 - j)];
            u[(size_t) (n - 1 - i) * n + (n - 1 - j)] = t;
        }
